$cats=$db->query("SELECT * FROM feedback_categories WHERE status='active' ORDER BY name")->fetchAll();$periods=$db->query("SELECT * FROM assessment_periods WHERE status IN ('active','closed') ORDER BY start_date DESC")->fetchAll();
echo '<div class="form-card"><h2>Employee Feedback</h2><p class="muted">Share qualitative feedback related to employee experience and retention.</p><form method="post">'.csrf_field().'<div class="form-grid"><div class="form-group"><label>Assessment Period</label><select name="period_id"><option value="">General / not tied to a period</option>';foreach($periods as $p)echo '<option value="'.(int)$p['id'].'">'.e($p['title']).'</option>';echo '</select></div><div class="form-group"><label>Category</label><select name="category_id" required><option value="">Select category</option>';foreach($cats as $c)echo '<option value="'.(int)$c['id'].'">'.e($c['name']).'</option>';echo '</select></div><div class="form-group full"><label>Your Feedback</label><textarea name="body" required></textarea><span class="help">Avoid including names or details that could unnecessarily identify another person.</span></div><div class="form-group full"><label>Submission Type</label><select name="is_anonymous"><option value="1">Anonymous — recommended</option><option value="0">Named feedback</option></select></div></div><button class="btn btn-primary" style="margin-top:14px">Submit Feedback</button></form></div><div class="notice" style="margin-top:14px">Anonymous feedback is stored without your employee ID. Named feedback is available only where policy permits.</div>';

